// Get the RSS articles from 'Limit to 10 Articles' node
const rssItems = $('Limit to 10 Articles').all();

// Get existing URLs from Supabase 'Get Recent URLs' node
const existingUrls = new Set(
  $('Get Recent URLs').all().map(item => item.json.url).filter(Boolean)
);

// Filter out articles whose URL already exists in Supabase
const newItems = rssItems.filter(item => {
  const articleUrl = item.json.link || item.json.url || '';
  return !existingUrls.has(articleUrl);
});

// Return new items (or empty array if all are duplicates)
return newItems.map(item => ({ json: item.json }));

