// Parse LLM JSON response and merge with article metadata
const llmOutput = $json.text || $json.response || '';

// Strip markdown code fences if present
const cleaned = llmOutput.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let scores;
try {
  scores = JSON.parse(cleaned);
} catch (e) {
  // If JSON parse fails, return item with error flag
  return {
    json: {
      error: 'LLM returned invalid JSON',
      raw_response: llmOutput,
      article_url: $('Loop Articles').item.json.link || '',
      article_title: $('Loop Articles').item.json.title || '',
      composite_score: 0
    }
  };
}

// Get article metadata from the RSS item in the loop
const rssItem = $('Loop Articles').item.json;

// Get Jina-extracted data if available
const jinaData = $('Jina Extract').item.json.data || {};

// Build a clean merged object
return {
  json: {
    // Article identity
    article_url: jinaData.url || rssItem.link || rssItem.url || '',
    article_title: jinaData.title || rssItem.title || '',
    article_content: jinaData.content || rssItem.description || '',
    published_at: rssItem.pubDate || rssItem.isoDate || '',
    source_feed: rssItem.feedUrl || '',
    // All 5 scores
    relevance_score: scores.relevance || 0,
    novelty_score: scores.novelty || 0,
    cross_domain_score: scores.cross_domain || 0,
    storytelling_score: scores.storytelling || 0,
    controversy_score: scores.controversy || 0,
    composite_score: scores.composite || 0,
    // Reasons
    relevance_reason: scores.relevance_reason || '',
    novelty_reason: scores.novelty_reason || '',
    cross_domain_reason: scores.cross_domain_reason || '',
    storytelling_reason: scores.storytelling_reason || '',
    controversy_reason: scores.controversy_reason || '',
    // Classification
    category: scores.suggested_pillar || 'general',
    suggested_pair_with: scores.suggested_pair_with || ''
  }
};

